from pathlib import Path
import ast,json,datetime,hashlib,sys
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'experiments/R2_open'
def read(p):return json.loads(p.read_text())
def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2))
path=read(OUT/'optimization_path.json');assert not any(r['id']=='R2_open_R4' for r in path['rounds'])
path['rounds'].append(dict(id='R2_open_R4',parents=['R2_open_R3','A2_information_R8'],status='preregistered',before=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),problem='B1 restricts certified clear to disk(center,20-r), which is a sufficient subset of the full all-vertex action region. A2 nearest projection ignores the route successor.',plan='Three variants: parent safe-disk route point; A2 exact nearest entry into full disk intersection; full-region entry+successor arc search including original action.',selection='All complete, Q4 exact; lowest Q3 mean on 16 fresh seeds x12x2. Keep original candidate in full-region search to avoid worsening fixed-state proxy, but full online task may differ.',seed_range=[42000036,42000051],guarantee='Each accepted q satisfies max_v dist(q,v)<=20; norms convex. Straight segment intersection is globally shortest fixed-state route; bounded arc search is only heuristic; original safe fallback always available.',cross_agent='Q3 idea sent to R3_open after root noted related Q4 safe-disk route study; they independently test disk first. No R3_open implementation has been copied.')))
save(OUT/'optimization_path.json',path)
with (OUT/'optimization_path.md').open('a') as f:f.write('\n\n## R4实验前：全部合法服务位置×后继路线\n\nA2 R8已在全顶点20米圆盘交集中找最近进入点；B1只在较小安全圆盘里兼顾后继位置。这里在R3上对照父安全圆盘、A2最近进入投影、全交集进入+离开费用。新路线方案检查直线段可行交点，否则对可行圆弧作有界采样和局部细化；始终含父点且全顶点复核，固定状态代理不会变差，但整体在线路线没有最优保证。开发42000036–42000051×12场景×2题。先比较再冻结，禁止按暴露场景决定策略。已互通知R3_open相关Q4方向，未复制其代码。\n')
a2=(ROOT/'experiments/20260911_agent_campaign/final_candidates/A2_information_R8.py').read_text();cls=next(n for n in ast.parse(a2).body if isinstance(n,ast.ClassDef) and n.name=='Solver');method=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='nearest_certified_clear');sys.path.insert(0,str(OUT/'research'));from build_candidate import rename
nearest='    '+rename(ast.get_source_segment(a2,method),{'dist':'_sp_dist'})+'\n\n'
component=(OUT/'research/r4_component.py').read_text()+ '\n'+nearest
s=(OUT/'snapshots/r3_solver.py').read_text().replace('BASELINE_CONFIG = dict(_sp_BASELINE_CONFIG)',component+'BASELINE_CONFIG = dict(_sp_BASELINE_CONFIG)',1).replace('parent = _DecisionSpatial if mode == 3 else _di_Solver','parent = _LensSpatial if mode == 3 else _di_Solver').replace('decision_gate="cost"),','decision_gate="cost", lens_clear="parent"),');ast.parse(s);(OUT/'snapshots/r4_development.py').write_text(s)
save(OUT/'research/r4_variants.json',[dict(name=n,candidate='experiments/R2_open/snapshots/r4_development.py',config={'lens_clear':g}) for n,g in [('parent','parent'),('nearest','nearest'),('route','route')]])
save(OUT/'research/r4_provenance.json',dict(parent_sha256=hashlib.sha256((OUT/'snapshots/r3_solver.py').read_bytes()).hexdigest(),a2_method='A2_information_R8.Solver.nearest_certified_clear unchanged apart from primitive rename',new='All-vertex feasible boundary arc enumeration and entry+successor proxy search; no inherited theorem claimed',development_sha256=hashlib.sha256(s.encode()).hexdigest()))
print('R4 preregistered and built')
